import {createClient} from 'contentful';
import type {ContentfulClientApi} from 'contentful';
import {
    getContentfulConfig,
    CONTENTFUL_PREVIEW_HOST,
    CONTENTFUL_DELIVERY_HOST,
} from '../config/contentful';

type UseContentfulClientArgs = {
    /** Whether the caller is requesting preview (draft) content, e.g. `?preview` is present. */
    preview: boolean;
};

type UseContentfulClientResult = {
    /** Memoised Contentful client, or `null` when required space/token config is missing. */
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    client: ContentfulClientApi<any> | null;
    /** `true` when preview was requested but no CPA token is configured (the non-prod gate). */
    previewUnavailable: boolean;
    /** `true` only when preview is requested AND a CPA token is available. */
    effectivePreview: boolean;
};

/**
 * Resolves a memoised Contentful client, shared by the `/preview` route and `?preview`
 * Experience pages so both select credentials identically.
 *
 * The preview (CPA) host + token are used only when preview is requested AND a preview
 * token is configured; otherwise the delivery (CDA) host + token are used. When preview is
 * requested but no token exists, `previewUnavailable` is `true` and the caller is expected
 * to fail explicitly — the CPA token is deliberately absent on staging/prod.
 *
 * @param preview whether the caller is requesting preview content.
 * @returns the resolved `client` (or `null` when config is missing), plus `previewUnavailable`
 *   and `effectivePreview` flags describing the resolved mode.
 */
export const useContentfulClient = ({
    preview,
}: UseContentfulClientArgs): UseContentfulClientResult => {
    const {spaceId, environment, previewAccessToken, accessToken} = getContentfulConfig() ?? {};
    const previewUnavailable = preview && !previewAccessToken;
    const effectivePreview = preview && !!previewAccessToken;
    const token = effectivePreview ? previewAccessToken : accessToken;
    const host = effectivePreview ? CONTENTFUL_PREVIEW_HOST : CONTENTFUL_DELIVERY_HOST;

    const client = useMemo(() => {
        if (!spaceId || !token) return null;
        return createClient({space: spaceId, environment, accessToken: token, host});
    }, [spaceId, environment, token, host]);

    return {client, previewUnavailable, effectivePreview};
};

