    // Falls back to delivery mode silently when no token is set (non-prod gate).
    const effectivePreview = isPreview && !!previewAccessToken
    const token = effectivePreview ? previewAccessToken : accessToken
    const host = effectivePreview ? CONTENTFUL_PREVIEW_HOST : CONTENTFUL_DELIVERY_HOST

    const client = useMemo(() => {
        if (!spaceId || !token) return null
        return createClient({space: spaceId, environment, accessToken: token, host})
    }, [spaceId, environment, token, host])

    if (previewUnavailable) {
        return (
            <Box p={8}>
                <Text color="red.500">
                    Preview is not enabled in this environment.
                </Text>
            </Box>
        )
    }

    if (!client) {
        return (
            <Box p={8}>
                <Text color="red.500">Contentful configuration is missing — cannot render this page.</Text>
            </Box>
        )
    }

    return <ExperienceFetch client={client} slug={slug} locale={locale} isPreview={effectivePreview} />
}

const Experience = () => {
    const {pathname, search} = useLocation()
    const slug = pathname.slice(1) // strip leading '/'
    const isPreview = new URLSearchParams(search).has('preview')

    return <ExperiencePage slug={slug} isPreview={isPreview} />
}

Experience.getTemplateName = () => 'experience';

export default Experience;
